#include <cstdio>
#include <vector>
using namespace std;
typedef long long ll;
const int LIM = 1000001;
vector<int> primes;
bool comp[1000001];
int main(){
    for(int i=2;i<LIM;i++){
        if(!comp[i]){ primes.push_back(i); for(ll j=(ll)i*i;j<LIM;j+=i) comp[j]=true; }
    }
    int n; scanf("%d",&n);
    for(int i=0;i<n;i++){
        ll lo,hi; scanf("%lld %lld",&lo,&hi);
        ll count=0;
        for(int p: primes){
            ll val=(ll)p*p;
            if(val>hi) break;
            while(val<=hi){
                if(val>=lo) count++;
                val*=p;
            }
        }
        printf("%lld\n",count);
    }
}

#include <cstdio>
